export const getObjectInfiniteQueryKey = (options: Options<GetObjectData>): QueryKey<Options<GetObjectData>> => createQueryKey('getObject', options, true);

/**
 * Original
 *
 * Return a bounded binary block authorized through its source; knowing a hash never grants access.
 */
export const getObjectInfiniteOptions = (options: Options<GetObjectData>) => {
    const opts = infiniteQueryOptions<GetObjectResponse2, GetObjectError, InfiniteData<GetObjectResponse2>, QueryKey<Options<GetObjectData>>, string | null | Pick<QueryKey<Options<GetObjectData>>[0], 'body' | 'headers' | 'path' | 'query'>>(
    // @ts-ignore
    {
        queryFn: async ({ pageParam, queryKey, signal }) => {
            // @ts-ignore
            const page: Pick<QueryKey<Options<GetObjectData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
                body: {
                    offset: pageParam
                }
            };
            const params = createInfiniteParams(queryKey, page);
            const { data } = await getObject({
                ...options,
                ...params,
                signal,
                throwOnError: true
            });
            return data;
        },
        queryKey: getObjectInfiniteQueryKey(options)
    });
    return opts as Omit<typeof opts, 'initialData'>;
};

